import unittest

from billing.invoice import Line, total


class QuantityTest(unittest.TestCase):
    def test_quantity_above_one_is_counted(self):
        self.assertEqual(total([Line("tea", 250, 3)]), 750)

    def test_default_quantity_is_one(self):
        self.assertEqual(total([Line("cake", 400)]), 400)


if __name__ == "__main__":
    unittest.main()
